// Secure application with proper error handling and input validation
// Focus on security best practices

const express = require('express');
const { body, query, validationResult } = require('express-validator');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss');
const app = express();
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Trust proxy if behind a load balancer
app.set('trust proxy', 1);

// Security middleware
app.use(helmet());

// Rate limiting to prevent DDoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests, please try again later'
    });
  }
});

// Apply rate limiting to all routes, except /health
app.use(limiter);
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Parse JSON bodies with size limit to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// XSS sanitization middleware
const sanitizeMiddleware = (req, res, next) => {
  if (req.body) {
    // Sanitize all string values in req.body
    for (const key in req.body) {
      if (typeof req.body[key] === 'string') {
        req.body[key] = xss(req.body[key]);
      }
    }
  }
  if (req.query) {
    // Sanitize query parameters
    for (const key in req.query) {
      if (typeof req.query[key] === 'string') {
        req.query[key] = xss(req.query[key]);
      }
    }
  }
  next();
};

app.use(sanitizeMiddleware);

// Input validation middleware
const validate = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));
    const errors = validationResult(req);

    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array().map(err => ({
          field: err.path,
          message: err.msg
        }))
      });
    }
    next();
  };
};

// User validation rules
const userValidationRules = [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .escape(), // Escape HTML to prevent XSS
  body('email')
    .trim()
    .isEmail()
    .withMessage('Please provide a valid email address')
    .normalizeEmail(), // Normalize email to lowercase
  body('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer')
];

// General query parameter validation
const queryValidationRules = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer')
];

// GET /users route with validation
app.get('/users', queryValidationRules, validate(queryValidationRules), (req, res) => {
  try {
    const { limit = 10, offset = 0 } = req.query;
    const parsedLimit = Math.min(Math.max(parseInt(limit), 1), 100);
    const parsedOffset = Math.max(parseInt(offset), 0);

    // Simulated user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply limit/offset
    const paginatedUsers = users
      .slice(parsedOffset, parsedOffset + parsedLimit);

    res.json({
      users: paginatedUsers,
      pagination: {
        limit: parsedLimit,
        offset: parsedOffset,
        total: users.length
      }
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// POST /users route with validation
app.post('/users', userValidationRules, validate(userValidationRules), (req, res) => {
  try {
    const { name, email } = req.body;

    // Simulated user creation
    const newUser = {
      id: users.length + 1,
      name: name,
      email: email
    };

    // Store user (in real app, save to database here)
    users.push(newUser);

    res.status(201).json({
      message: 'User created successfully',
      user: newUser
    });
  } catch (error) {
    console.error('Error creating user:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: 'The requested endpoint does not exist'
  });
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Log error details (in production, use proper logging service)
  if (process.env.NODE_ENV === 'development') {
    console.error('Error stack:', err.stack);
  }

  // Don't expose internal error details in production
  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'An unexpected error occurred'
  });
});

// Graceful shutdown handling
const cleanup = async () => {
  console.log('Shutting down gracefully...');
  try {
    // Close server here
    process.exit(0);
  } catch (error) {
    console.error('Error during cleanup:', error);
    process.exit(1);
  }
};

process.on('SIGTERM', cleanup);
process.on('SIGINT', cleanup);

// Start server
app.listen(PORT, HOST, () => {
  console.log(`🚀 Secure server running on http://${HOST}:${PORT}`);
});

module.exports = app;

