// Secure application with proper error handling and input validation
const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// ============== SECURITY MIDDLEWARE ==============

// Helmet for HTTP security headers
app.use(helmet());

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});
app.use('/api/', limiter);

// CORS configuration - restrict to specific origins
const whitelist = ['https://your-allowed-domain.com', 'http://localhost:3000'];
const corsOptions = {
  origin: function (origin, callback) {
    if (whitelist.indexOf(origin) !== -1 || !origin) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// ============== REQUEST PARSING & VALIDATION ==============

// Parse JSON with size limit
app.use(express.json({
  limit: '10kb', // Prevents memory exhaustion attacks
  verify: (req, res, buf, encoding) => {
    // Detect potential JSON payload attacks
    if (buf.length > 100000) { // 100KB limit for verification
      throw new Error('Payload too large');
    }
  }
}));

// Parse URL-encoded data
app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// ============== ROUTES WITH PROPER ERROR HANDLING ==============

// Health check endpoint with basic validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if present
    if (req.query) {
      // You could add schema validation here
    }

    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    // Don't expose detailed errors to clients
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const allowedSortFields = ['id', 'name', 'email'];
    const allowedSortOrders = ['asc', 'desc'];

    let sortBy = req.query.sort || 'id';
    let sortOrder = req.query.order || 'asc';

    // Validate sort field
    if (!allowedSortFields.includes(sortBy)) {
      sortBy = 'id'; // Default to safe value
    }

    // Validate sort order
    if (!allowedSortOrders.includes(sortOrder.toLowerCase())) {
      sortOrder = 'asc'; // Default to safe value
    }

    // Validate pagination parameters
    const page = Math.min(Math.max(parseInt(req.query.page) || 1, 1), 1000); // Max 1000 pages
    const limit = Math.min(Math.max(parseInt(req.query.limit) || 10, 1), 100); // Max 100 items per page

    // Pagination logic (stub)
    const skip = (page - 1) * limit;
    const results = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ].slice(skip, skip + limit);

    res.json({
      data: results,
      pagination: {
        page,
        limit,
        total: results.length,
        totalPages: Math.ceil(results.length / limit)
      }
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// ============== ERROR HANDLING MIDDLEWARE ==============

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Endpoint not found'
  });
});

// Global error handler - MUST be last middleware
app.use((err, req, res, next) => {
  // Log the error for debugging (in production, use proper logging)
  console.error('Unhandled error:', err);

  // Send appropriate response without exposing sensitive details
