const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const morgan = require('morgan');
const xss = require('xss-clean');
const validator = require('express-validator');
const { body, validationResult } = validator;

// Load environment variables
require('dotenv').config();

const app = express();

// Security middleware stack
app.use(helmet()); // Security headers
app.use(xss()); // Sanitize all inputs
app.use(express.json()); // Parse JSON bodies
app.use(express.urlencoded({ extended: true })); // Parse URL-encoded bodies

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later' },
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Logging (only in development)
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('dev'));
}

// Request ID tracking
const crypto = require('crypto');
app.use((req, res, next) => {
  req.id = crypto.randomUUID();
  res.set('X-Request-ID', req.id);
  next();
});

// Error handling middleware (MUST be last)
app.use((err, req, res, next) => {
  console.error(`[${req.id}] Error:`, err.message, err.stack);

  // Don't send stack traces to clients in production
  const statusCode = err.statusCode || 500;
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(statusCode).json({
    error: isProduction && statusCode === 500
      ? 'Internal server error'
      : err.message,
    ...(isProduction === false && { stack: err.stack }),
    ...(isProduction === false && { requestId: req.id })
  });
});

// Health check endpoint (no input validation needed)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    ...(process.env.NODE_ENV && { environment: process.env.NODE_ENV })
  });
});

// Validation middleware helper
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Invalid input',
      requestId: req.id,
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

// Example route with validation
app.get(
  '/users',
  [
    // Validate query parameters
    body('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    body('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer'),
  ],
  validateRequest,
  (req, res) => {
    try {
      const { limit = 10, offset = 0 } = req.body;
      // Simulated data
      const users = Array.from({ length: limit }, (_, i) => ({
        id: i + 1 + offset,
        name: `User ${i + 1 + offset}`,
        email: `user${i + 1 + offset}@example.com`
      }));

      res.json({
        requestId: req.id,
        data: users,
        meta: {
          limit,
          offset,
          total: 100 // Mock total count
        }
      });
    } catch (err) {
      next(err);
    }
  }
);

// Example protected route requiring authentication
const authenticate = (req, res, next) => {
  // In production, validate JWT token, API key, etc.
  if (!req.headers.authorization) {
    return res.status(401).json({
      error: 'Unauthorized',
      requestId: req.id
    });
  }
  next();
};

// Example POST route with full validation and sanitization
app.post(
  '/users',
  [
    body('name')
      .notEmpty()
      .trim()
      .isLength({ min: 2, max: 50 })
      .escape() // Escape HTML characters
      .withMessage('Name must be between 2 and 50 characters'),
    body('email')
      .isEmail()
      .normalizeEmail()
      .withMessage('Please provide a valid email address'),
    body('password')
      .isLength({ min: 8 })
      .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/)
      .withMessage('Password must be at least 8 characters with uppercase, lowercase, and number'),
  ],
  validateRequest,
  authenticate,
  (req, res) => {
    try {
      // Additional sanitization after validation
      const user = {
        id: crypto.randomUUID(),
        ...req.body, // All data has been validated and sanitized by express-validator
        createdAt: new Date().toISOString()
      };

      // In production: hash password before storing
      // const hashedPassword = await bcrypt.hash(user.password, 10);
      // user.password = hashedPassword;

      res.status(201).json({
        success: true,
        requestId: req.id,
        data: user
      });
    } catch (err) {
      next(err);
    }
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    requestId: req.id,
    path: req.path
  });
});

// Start server
const PORT = process.env.PORT || 3000;
const startServer = () => {
  return new Promise((resolve) => {
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
      console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
      console.log(`Request ID: ${crypto.randomUUID()}`);
      resolve();
    });
  });
};

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  process.exit(0);
});

// Export for testing
module.exports = app;

// Start server only if this is the main module
if (require.main === module) {
  startServer().catch(console.error);
}

