const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true, // return rate limit info in cors & ratelimit-* headers
  legacyHeaders: false, // Disable deprecated ratelimit-* headers
  skip: (req) => req.path === '/health', // Skip health check endpoint

  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests',
      message: 'Please try again later',
      retryAfter: '15 minutes'
    });
  }
});

app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// CORS configuration
app.use((req, res, next) => {
  const allowedOrigins = ['http://localhost:3000', 'http://localhost:5500'];
  const origin = req.headers.origin;

  // In production, replace localhost with your actual domain
  if (allowedOrigins.includes(origin) || !origin) {
    res.setHeader('Access-Control-Allow-Origin', origin || '*');
    res.setHeader('Access-Control-Allow-Credentials', 'true');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  }

  // Handle preflight requests
  if (req.method === 'OPTIONS') {
    return res.sendStatus(204);
  }

  next();
});

// Health endpoint - no rate limiting, always available
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Users endpoint with validation
app.get('/users', validateUserInput, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // If query parameters provided, filter users (security concern: potential DoS)
    // Note: This could be enhanced with proper database queries
    if (req.query.name || req.query.email) {
      const filteredUsers = users.filter(user => {
        const matchName = !req.query.name || user.name.toLowerCase().includes(req.query.name.toLowerCase());
        const matchEmail = !req.query.email || user.email.toLowerCase().includes(req.query.email.toLowerCase());
        return matchName && matchEmail;
      });

      return res.json(filteredUsers);
    }

    res.json(users);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Handle validation errors
  if (err.name === 'ValidationError') {
    return res.status(400).json({ error: err.message });
  }

  // Handle rate limit errors
  if (err.status === 429) {
    return res.status(429).json({
      error: err.message,
      retryAfter: err.retryAfter
    });
  }

  // Generic error response
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: 'An unexpected error occurred',
    message: process.env.NODE_ENV === 'development' ? err.message : undefined
  });
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// Graceful shutdown handling
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Handle SIGTERM and SIGINT for graceful shutdown
const shutdown = async () => {
  console.log('Received graceful shutdown signal...');
  server.close(async () => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;

