    const strLen = Buffer.byteLength(str, 'utf8');
    return strLen > 0 && strLen <= maxLength;
  }
};

// Validation middleware
const validateInput = (schema) => {
  return (req, res, next) => {
    const errors = [];

    for (const [field, validator] of Object.entries(schema)) {
