      if (validator.required && (value === undefined || value === null)) {
        errors.push(`${field} is required`);
        continue;
      }

      if (value !== undefined && value !== null) {
        if (typeof validator === 'function' && !validator(value)) {
          errors.push(`${field} is invalid`);
