// Sanitize function to prevent XSS (DOMPurify alternative)
function xss(str) {
  if (typeof str !== 'string') return str;

  const entityMap = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#x27;',
    // Add other entities as needed
  };

  return str.replace(/[&<>"']/g, function (s) {
    return entityMap[s];
