/**
 * Environment Configuration Validator
 * Checks all required environment variables for the app
 */

const requiredVars = ['NODE_ENV'];
const optionalVars = ['PORT', 'HOST', 'CORS_ORIGIN', 'RATE_LIMIT_WINDOW', 'RATE_LIMIT_MAX'];

console.log('🔍 Validating environment configuration...\n');

