requiredVars.forEach(envVar => {
  if (!process.env[envVar]) {
    missingRequired.push(envVar);
  }
});

if (missingRequired.length > 0) {
  console.error('❌ Missing required environment variables:');
  missingRequired.forEach(varName => {
    console.error(`   - ${varName}`);
  });
  process.exit(1);
} else {
  console.log('✓ All required environment variables are set');
}

// Check optional variables with their defaults
console.log('\n📋 Optional environment variables:');
let envVariablesFound = 0;

optionalVars.forEach(envVar => {
  const value = process.env[envVar];
  if (value) {
    console.log(`   ✓ ${envVar} = ${value}`);
    envVariablesFound++;
  } else {
    console.log(`   ○ ${envVar} not set (using default)`);
  }
});

if (envVariablesFound > 0) {
  console.log(`\n   ${envVariablesFound} optional variables configured`);
}

// Validate sensitive values (warning only)
console.log('\n⚠️  Security Checks:');

if (process.env.NODE_ENV === 'production') {
  if (process.env.PORT === '3000') {
    console.warn('   ⚠️  Warning: Running on default port 3000 in production');
  }

  if (process.env.CORS_ORIGIN === '*') {
    console.error('   ❌ CRITICAL: CORS_ORIGIN set to "*" (very insecure for production)');
