// Secure Express Application with Enhanced Error Handling and Input Validation
const express = require('express');
const helmet = require('helmet');
const morgan = require('morgan');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// === SECURITY MIDDLEWARE ===

// Helmet: Sets various HTTP headers for security
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  frameguard: { action: 'deny' },
  hsts: { maxAge: 31536000, includeSubDomains: true },
  xssFilter: true,
  noSniff: true,
}));

// CORS configuration - limit allowed origins
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*',
  credentials: true,
}));

// Request logging for security auditing
app.use(morgan('combined', {
  skip: (req, res) => res.statusCode < 400
}));

// Rate limiting - prevent brute force and DDoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api', limiter);

// Rate limiting for error-prone endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // 10 requests per 15 minutes
  message: 'Too many requests. Please wait before trying again.',
});
app.use('/health', strictLimiter);

// Body size limits - prevent memory exhaustion
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// === INPUT VALIDATION MIDDLEWARE ===

// Validate request bodies
const validationMiddleware = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    const formattedErrors = errors.array().map(error => ({
      field: error.path,
      message: error.msg
    }));
    return res.status(400).json({
      success: false,
      error: 'Validation failed',
      details: formattedErrors
    });
  }
  next();
};

// Validation rules for user data
const userValidationRules = [
  body('name')
    .trim()
    .escape()
    .isLength({ min: 3, max: 100 })
    .withMessage('Name must be between 3 and 100 characters')
    .notEmpty()
    .withMessage('Name is required'),
  body('email')
    .trim()
    .normalizeEmail()
    .isEmail()
    .withMessage('Invalid email address')
    .notEmpty()
    .withMessage('Email is required'),
  body('email')
    .custom(async (value) => {
      // In production, check if email already exists
      const emailExists = await checkEmailExists(value);
      if (emailExists) {
        throw new Error('Email already registered');
      }
      return true;
    })
];

// === ROUTES ===

// Health endpoint with strict rate limiting
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      version: '1.0.0'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error'
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Add input validation for query parameters
    if (req.query.email && !isValidEmail(req.query.email)) {
      return res.status(400).json({
        success: false,
        error: 'Invalid email format in query parameter'
      });
    }

    // Simulate database query
    const users = [
      { id: 1, name: 'Alice Johnson', email: 'alice@example.com', created_at: new Date().toISOString() },
      { id: 2, name: 'Bob Smith', email: 'bob@example.com', created_at: new Date().toISOString() },
    ];

    // Filter users if email is provided
    let filteredUsers = users;
    if (req.query.email) {
      filteredUsers = users.filter(user => user.email.toLowerCase() === req.query.email.toLowerCase());
    }

    res.status(200).json({
      success: true,
      data: filteredUsers,
      count: filteredUsers.length
    });
  } catch (error) {
    console.error('Users query error:', error);
    res.status(500).json({
      success: false,
      error: 'Failed to fetch users'
    });
  }
});

// POST endpoint example with validation (future-proofing)
app.post('/users', userValidationRules, validationMiddleware, async (req, res) => {
  try {
    // Validate request body
    const { name, email } = req.body;

    // Email exists check (mock)
    const emailExists = await checkEmailExists(email);

    if (emailExists) {
      return res.status(409).json({
        success: false,
        error: 'Email already registered'
      });
    }

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: {
        id: users.length + 1,
        name,
        email,
        created_at: new Date().toISOString()
      }
    });
  } catch (error) {
    console.error('User creation error:', error);
    if (error.name === 'ValidationError') {
      return res.status(400).json({
        success: false,
        error: error.message
      });
    }
    res.status(500).json({
      success: false,
      error: 'Internal server error'
    });
  }
});

// === ERROR HANDLING MIDDLEWARE ===

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Endpoint not found',
    path: req.path
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    ip: req.ip,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Sobscure sensitive error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  if (isDevelopment) {
    res.status(err.statusCode || 500).json({
      success: false,
      error: err.message,
      stack: err.stack
    });
  } else {
    res.status(err.statusCode || 500).json({
      success: false,
      error: 'Internal server error',
      // Optionally log to error tracking service
      // requestId: req.id // from external services
    });
  }
});

// === HELPER FUNCTIONS ===

// Email validation helper
function isValidEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

// Mock function to check email existence
async function checkEmailExists(email) {
  // In production, you would check this in your database
  const mockDatabase = [
    { name: 'Alice Johnson', email: 'alice@example.com' },
    { name: 'Bob Smith', email: 'bob@example.com' },
    { name: 'Charlie Brown', email: 'charlie@example.com' },
  ];
  return mockDatabase.some(user => user.email === email);
}

// Graceful shutdown handler
const shutdown = () => {
  console.log('Received shutdown signal. Closing server gracefully...');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown after timeout');
    process.exit(1);
  }, 10000);
};

// Listen on port with proper error handling
const server = app.listen(process.env.PORT || 3000, () => {
  console.log(`Secure server running on port ${process.env.PORT || 3000}`);
});

// Handle process termination signals
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;

