# Security Review: app.js - Error Handling & Input Validation

## Executive Summary
The current `app.js` is a minimal Express application with basic routing. While it doesn't have exposed attack surfaces yet, it lacks critical security protections that should be implemented before production deployment.

---

## Critical Security Issues & Recommendations

### 1. Missing Input Validation ⚠️ **CRITICAL**

**Current State:**
- No validation of request parameters
- No sanitization of user input
- Exposes arbitrary data without validation

**Security Risks:**
- **Injection Attacks**: Potential for SQL (if database added), NoSQL, or command injection
- **DoS Vulnerabilities**: Request smuggling, parameter pollution
- **Data Integrity**: No validation of data types, formats, or constraints

**Recommended Fixes:**

```javascript
const { body, query, param, validationResult } = require('express-validator');

// Add validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation Failed',
      details: errors.array()
    });
  }
  next();
};

// Example: Add validation to /users route
app.get('/users', [validateRequest], async (req, res) => {
  try {
    // Only return users if user is authenticated
    if (!req.user) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    // Validate query parameters if used
    const { page = 1, limit = 10 } = req.query;
    const pageNumber = parseInt(page);
    const limitNumber = parseInt(limit);

    if (isFinite(pageNumber) && pageNumber < 1) {
      return res.status(400).json({ error: 'Page must be >= 1' });
    }
    if (isFinite(limitNumber) && limitNumber < 1 || limitNumber > 100) {
      return res.status(400).json({ error: 'Limit must be between 1 and 100' });
    }

    res.json(await getUsers(pageNumber, limitNumber));
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

---

### 2. Missing Exposure Control ⚠️ **HIGH**

**Current State:**
```javascript
app.get('/users', (req, res) => {
  res.json([...]); // Undocumented, unknown to user
});
```

**Security Risks:**
- **CSRF Susceptibility**: No CSRF protection
- **XSS Risk**: No content security policy
- **Information Leakage**: Accessible without authentication

**Recommended Fixes:**

```javascript
const helmet = require('helmet');
const csrf = require('csurf');
const rateLimit = require('express-rate-limit');

// Apply security headers immediately
app.use(helmet({
  contentSecurityPolicy: true,
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  xFrameOptions: { action: 'deny' },
  xXssProtection: true
}));

// Rate limiting to prevent abuse
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later' }
});

app.use('/users', apiLimiter);

// CSRF protection for state-changing operations (future endpoints)
if (process.env.NODE_ENV === 'production') {
  app.use(csrf({ cookie: true }));
}
```

---

### 3. Insufficient Error Handling ⚠️ **HIGH**

**Current State:**
- Generic error handling only at endpoint level
- No error middleware
- May return stack traces or sensitive information

**Security Risks:**
- **Information Disclosure**: Stack traces may expose file paths or code structure
- **Debug Mode Leaks**: Development errors visible in production

**Recommended Fixes:**

```javascript
// Global error handling middleware (must be after all routes)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Determine status code
  const status = err.status || err.statusCode || 500;

  // In production, don't expose stack traces
  const errorResponse = {
    error: status === 500 ? 'Internal server error' :
           status === 404 ? 'Resource not found' : err.message
  };

  if (process.env.NODE_ENV === 'development') {
    errorResponse.stack = err.stack;
    errorResponse.details = err.details; // For validation errors
  }

  res.status(status).json(errorResponse);
});

// Add .catch() to all asynchronous route handlers
app.get('/users', async (req, res) => {
  try {
    // ...
  } catch (error) {
    res.locals.error = error;
    next(error);
  }
});

// Example: Better health endpoint
app.get('/health', (req, res) => {
  try {
    // Add checks for external dependencies
    res.json({
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memoryUsage: process.memoryUsage()
    });
  } catch (error) {
    res.status(503).json({
      status: 'unhealthy',
      error: 'Health check failed'
    });
  }
});
```

---

### 4. Missing Security Settings ⚠️ **MEDIUM**

**Current State:**
- No trust proxy configuration
- No cookie security settings
- No limiting of payload size

**Security Risks:**
- **IP Spoofing**: Trusting client IP directly
- **Session Hijacking**: Weak cookie defaults
- **Memory Exhaustion**: No body size limits

**Recommended Fixes:**

```javascript
// ConfigureExpress security
const configureExpress = (app) => {
  // Trust proxy (only if behind nginx/reverse proxy)
  if (process.env.TRUST_PROXY) {
    app.set('trust proxy', process.env.TRUST_PROXY);
  }

  // Body size limits (prevent DoS)
  app.use(express.json({
    limit: '1mb'
  }));

  app.use(express.urlencoded({
    extended: true,
    limit: '1mb'
  }));

  // Cookie settings
  app.use((req, res, next) => {
    res.cookie('express.sid', null, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      path: '/',
      maxAge: 7 * 24 * 60 * 60 * 1000 // 7 days
    });
    next();
  });

  // Request logging for security monitoring
  app.use((req, res, next) => {
    if (process.env.ENABLE_SECURITY_LOGGING) {
      console.log(`[${timestamp}] IP=${req.ip} METHOD=${req.method} PATH=${req.path}`);
    }
    next();
  });
};

configureExpress(app);
```

---

### 5. Missing Authentication & Authorization ⚠️ **CRITICAL**

**Current State:**
- No authentication for any endpoints
- No authorization checks
- No rate limiting

**Security Risks:**
- **Unrestricted Access**: Anyone can access /users
- **Privilege Escalation**: No role-based access control
- **Web Scraping DoS**: API is vulnerable to massive scraping

**Recommended Fixes:**

```javascript
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');

// Middleware for authentication
const authenticate = async (req, res, next) => {
  try {
    const token = req.headers.authorization?.replace('Bearer ', '');

    if (!token) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
};

// Middleware for authorization (role-based)
const authorize = (...roles) => (req, res, next) => {
  if (!roles.includes(req.user.role)) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  next();
};

// Protect sensitive endpoint
app.get('/users', [authenticate, authorize('admin', 'manager')], async (req, res) => {
  // Server accepts content only from authorized users
  res.json(await getUsers());
});

// Public endpoint with stricter rate limit
const publicLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 50,
  message: 'Too many attempts'
});

app.get('/health', publicLimiter, (req, res) => {
  res.json({ status: 'ok' });
});
```

---

### 6. Missing Input Sanitization ⚠️ **MEDIUM**

**Current Risks:**
- JSON injection when handling POST/PUT data
- HTML/JS injection if rendering user content

**Recommended Fixes:**

```javascript
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');

// Sanitize against NoSQL injection and XSS
app.use(mongoSanitize()); // MongoDB/NoSQL injection protection
app.use(xssClean());      // XSS protection

// Validate input with express-validator
app.post('/users', [
  body('email').isEmail().normalizeEmail(),
  body('name').isString().trim().isLength({ min: 2, max: 100 }),
  body('age').optional().isInt({ min: 0, max: 120 }),
  validateRequest
], async (req, res) => {
  const sanitizedUser = {
    email: sanitizeEmail(req.body.email), // Add custom sanitization
    name: sanitizeName(req.body.name)
  };
  // Save to database
});
```

---

## Complete Recommended Implementation

Here's a complete, security-hardened version:

```javascript
// app.js - Security-hardened version
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xssClean = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const jwt = require('jsonwebtoken');
const { body, validationResult } = require('express-validator');
const app = express();

// Security middleware - order matters!
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    success: false,
    error: 'Too many requests. Please try again later.'
  }
});

// Additional strict limit for API endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: {
    success: false,
    error: 'API rate limit exceeded. Please wait before retrying.'
  }
});

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// Authentication middleware
const authenticate = async (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({
        success: false,
        error: 'Authorization token required'
      });
    }

    const token = authHeader.split(' ')[1];
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = { userId: decoded.id, role: decoded.role };
    next();
  } catch (error) {
    return res.status(401).json({
      success: false,
      error: 'Invalid or expired token'
    });
  }
};

// Configure Express
const configureApp = () => {
  // Apply security headers
  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        imgSrc: ["'self'", 'data:', 'https:'],
        connectSrc: ["'self'"]
      }
    },
    hsts: {
      maxAge: 31536000,
      includeSubDomains: true,
      preload: true
    }
  }));

  // Trust proxy
  if (process.env.TRUST_PROXY) {
    app.set('trust proxy', process.env.TRUST_PROXY);
  }

  // Body parsing with size limits
  app.use(express.json({
    limit: '1mb',
    verify: (req, res, buf) => {
      // Track request size for monitoring
      req.bodyLength = buf.length;
    }
  }));

  app.use(express.urlencoded({
    extended: true,
    limit: '1mb'
  }));

  // Input sanitization
  app.use(mongoSanitize()); // NoSQL injection
  app.use(xssClean());      // XSS

  // Security logging
  if (process.env.ENABLE_SECURITY_LOGGING === 'true') {
    app.use((req, res, next) => {
      console.log(`[${new Date().toISOString()}] IP: ${req.ip} ${req.method} ${req.path}`);
      if (req.bodyLength > 1000000) {
        console.warn('Large payload detected:', req.ip, req.path, req.bodyLength);
      }
      next();
    });
  }

  // Security headers middleware
  app.use((req, res, next) => {
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
    next();
  });

  // Routes
  // Public endpoint (rate limited)
  app.get('/health', apiLimiter, (req, res) => {
    res.json({
      success: true,
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      nodeVersion: process.version
    });
  });

  // Protected endpoint (authenticated + rate limited)
  app.get('/users', [
    authenticate,
    strictLimiter,
    (req, res, next) => {
      // Input validation for query params
      const { page = 1, limit = 10 } = req.query;
      const pageInt = parseInt(page);
      const limitInt = parseInt(limit);
      req.validatedQuery = { page: isFinite(pageInt) ? Math.max(1, pageInt) : 1 };
      req.validatedQuery.limit = Math.min(100, Math.max(1, isFinite(limitInt) ? limitInt : 10));
      next();
    }
  ], async (req, res) => {
    try {
      // You would fetch users here
      // const users = await UserService.getUsers(
      //   req.validatedQuery.page,
      //   req.validatedQuery.limit
      // );

      res.json({
        success: true,
        data: [], // Replace with actual data
        pagination: {
          page: req.validatedQuery.page,
          limit: req.validatedQuery.limit
        }
      });
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({
        success: false,
        error: 'Internal server error'
      });
    }
  });

  // Error handling - must be last
  app.use((req, res, next) => {
    res.status(404).json({
      success: false,
      error: 'Endpoint not found'
    });
  });

  app.use((err, req, res, next) => {
    console.error('Unhandled error:', err);
    res.status(err.status || 500).json({
      success: false,
      error: process.env.NODE_ENV === 'production' ?
             'Internal server error' : err.message
    });
  });
};

configureApp();

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
});

module.exports = app;
```

---

## Testing Checklist ✓

- [ ] Test with invalid input (malformed JSON, empty values)
- [ ] Test injection attempts (SQL/NoSQL injection, XSS payloads)
- [ ] Test rate limiting functionality
- [ ] Verify error messages don't reveal stack traces
