    limit: '1mb'
  }));

  app.use(express.urlencoded({
    extended: true,
    limit: '1mb'
  }));

  // Cookie settings
  app.use((req, res, next) => {
    res.cookie('express.sid', null, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
