const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

// Create app with security middleware
const app = express();

// Security middleware - add security headers
app.use(helmet());

// Trust proxy for rate limiting behind load balancers
app.set('trust proxy', 1);

// Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  message: {
    error: 'Too many requests, please try again later.',
    retryAfter: '15 minutes'
  },
  standardHeaders: true,
  legacyHeaders: false,
});
// Apply rate limiting to all routes except health
app.use('/users', limiter);

// Parse JSON and URL-encoded bodies
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateUserInput = [
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 100 }).withMessage('Name must be 2-100 characters'),
  body('email')
    .trim()
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format')
    .normalizeEmail(),
];

// Health endpoint with no rate limiting and minimal telemetry
app.get('/health', (req, res) => {
  const healthInfo = {
    status: 'ok',
    uptime: process.uptime(),
    timestamp: new Date().toISOString()
  };

  // Only expose minimal health data
  res.set('Cache-Control', 'no-store');
  res.set('X-Content-Type-Options', 'nosniff');
  res.json(healthInfo);
});

// Users endpoint with validation and error handling
app.get('/users', (req, res) => {
  try {
    // Return only safe user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.set('Cache-Control', 'no-cache');
    res.set('Content-Type', 'application/json');
    res.set('X-Content-Type-Options', 'nosniff');
    res.json(users);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development'
        ? 'Failed to retrieve users'
        : undefined
    });
  }
});

// Create user endpoint with full validation
app.post('/users', validateUserInput, (req, res) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array()
      });
    }

    const { name, email } = req.body;

    // Additional runtime validation
    if (!name || !email) {
      return res.status(400).json({ error: 'Name and email are required' });
    }

    // Sanitize and construct user (in real app, save to database)
    const newUser = {
      id: Date.now(),
      name: name.trim(),
      email: email.trim()
    };

    // Set appropriate headers
    res.set('Content-Type', 'application/json');
    res.set('X-Content-Type-Options', 'nosniff');

    res.status(201).json({
      message: 'User created successfully',
      user: newUser
    });
  } catch (error) {
    console.error('Error creating user:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development'
        ? error.message
        : undefined
    });
  }
});

// Generic error handler - must be last
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Set appropriate status code, default to 500
  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    error: err.message || 'Internal server error',
    ...(process.env.NODE_ENV === 'development' ? { details: err.stack } : {})
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path
  });
});

// Graceful shutdown
const server = app.listen(3000, () => {
  console.log(`Server running on port 3000 (${process.env.NODE_ENV || 'production'})`);
  console.log(`Health endpoint: http://localhost:3000/health`);
});

// Handle shutdown gracefully
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

