const express = require('express');
const app = express();
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult, query } = require('express-validator');
const { sanitizeQuery, sanitizeBody, sanitizeParam } = require('express-mongo-sanitize');

// Security headers middleware
app.use(helmet());

// Security middleware
app.use(express.json({ limit: '10kb' })); // Limit body size to prevent DoS
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
app.use(sanitizeQuery());
app.use(sanitizeBody());
app.use(sanitizeParam());

// Rate limiting - prevent brute force and abuse
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use('/api', apiLimiter);

// Custom error handler middleware (must be after all routes)
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use a proper logging service)
  console.error('Error:', err);

  // Send user-friendly error response
  const statusCode = err.status || 500;
  const message = err.message || 'Internal Server Error';

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// Health check endpoint - no rate limiting needed
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

