  .trim()
  .isEmail()
  .normalizeEmail() // Convert to canonical form
  .escape() // Prevent XSS
  .withMessage('Valid email is required'),
(req, res, next) => {
  try {
    // Validate request body
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array()
      });
    }

