    const paginatedUsers = users.slice(numOffset, numOffset + numLimit);

    res.json({
      users: paginatedUsers,
      total: users.length,
      pagination: {
        limit: numLimit,
        offset: numOffset,
        hasMore: numOffset + numLimit < users.length
      }
